// Micro-bundler CommonJS → a single file for the browser.
// Takes the `tsc` output (build/src) and React from node_modules. No extra dependencies or Internet.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const entry = path.join(root, "build", "src", "main.js");
const dist = path.join(root, "dist");
const searchDirs = [path.join(root, "node_modules"), ...(process.env.NODE_PATH || "").split(path.delimiter).filter(Boolean)];
const ALIASES = {
  "react": "react/cjs/react.production.js",
  "react/jsx-runtime": "react/cjs/react-jsx-runtime.production.js",
  "react-dom": "react-dom/cjs/react-dom.production.js",
  "react-dom/client": "react-dom/cjs/react-dom-client.production.js",
  "scheduler": "scheduler/cjs/scheduler.production.js",
};

function resolvePkg(spec) {
  const rel = ALIASES[spec];
  if (!rel) throw new Error(`Dependency not allowed in the bundle: ${spec}`);
  for (const d of searchDirs) {
    const p = path.join(d, rel);
    if (fs.existsSync(p)) return p;
  }
  throw new Error(`${spec} not found (${rel}). Run npm install in frontend/.`);
}

function resolve(from, spec) {
  if (!spec.startsWith(".")) return resolvePkg(spec);
  const base = path.resolve(path.dirname(from), spec);
  for (const c of [base, base + ".js", path.join(base, "index.js")]) if (fs.existsSync(c) && fs.statSync(c).isFile()) return c;
  throw new Error(`Cannot resolve ${spec} from ${from}`);
}

const modules = new Map();
function add(file) {
  if (modules.has(file)) return modules.get(file).id;
  const rec = { id: modules.size, code: "", deps: {} };
  modules.set(file, rec);
  let code = fs.readFileSync(file, "utf8").replace(/process\.env\.NODE_ENV/g, '"production"').replace(/^\/\/# sourceMappingURL=.*$/m, "");
  const re = /\brequire\(\s*["']([^"']+)["']\s*\)/g;
  let m;
  while ((m = re.exec(code))) if (!(m[1] in rec.deps)) rec.deps[m[1]] = add(resolve(file, m[1]));
  rec.code = code;
  return rec.id;
}

const entryId = add(entry);
let out = `/* KAOSnt — local bundle generated by tools/bundle.mjs. Includes React (MIT licence). */\n(function(){"use strict";\nvar process={env:{NODE_ENV:"production"}};var defs={};var cache={};\nfunction req(id){if(cache[id])return cache[id].exports;var m={exports:{}};cache[id]=m;defs[id][0].call(m.exports,m,m.exports,function(s){var d=defs[id][1][s];if(d===undefined)throw new Error("Module not found: "+s);return req(d);});return m.exports;}\n`;
for (const [file, rec] of modules) out += `defs[${rec.id}]=[function(module,exports,require){\n${rec.code}\n},${JSON.stringify(rec.deps)}]; // ${path.relative(root, file).replace(/\\/g, "/")}\n`;
out += `req(${entryId});\n})();\n`;

fs.rmSync(dist, { recursive: true, force: true });
fs.mkdirSync(path.join(dist, "assets"), { recursive: true });
fs.writeFileSync(path.join(dist, "assets", "app.js"), out);
fs.copyFileSync(path.join(root, "src", "styles.css"), path.join(dist, "assets", "styles.css"));
fs.copyFileSync(path.join(root, "public", "index.html"), path.join(dist, "index.html"));
console.log(`Bundle: ${modules.size} modules, ${(out.length / 1024).toFixed(0)} KB → dist/`);
